private ServerReplace resolveTarget(String rawModel, String rawCode) {
    // 一级：纯数字按物料代码精确查
    if (StringUtils.isNumeric(rawCode)) {
        ServerReplace hit = queryByMaterialCode(rawCode);
        if (hit != null) {
            return hit;
        }
    }
    // 二级：括号里的 code 作为主查入口
    String bracket = extractBracket(rawModel);
    if (StringUtils.isNotBlank(bracket)) {
        ServerReplace hit = queryByMaterialCode(bracket);
        if (hit != null) {
            return hit;
        }
    }
    // 三级：去掉括号后缀按型号名查
    String pure = stripBracket(rawModel);
    ServerReplace hit = queryByModelName(pure);
    if (hit != null) {
        return hit;
    }
    // 四级：仍查不到就返回空，由调用方决定是否原样展示
    return null;
}

private static final ExecutorService POOL = new ThreadPoolExecutor(
        4, 8, 60L, TimeUnit.SECONDS,
        new LinkedBlockingQueue<>(200),
        new ThreadPoolExecutor.CallerRunsPolicy());

public Map<String, AlgoDetailResponse> batchQuery(List<String> algoIds) {
    if (CollectionUtils.isEmpty(algoIds)) {
        return Collections.emptyMap();
    }
    Map<String, AlgoDetailResponse> result = new ConcurrentHashMap<>(algoIds.size());
    List<CompletableFuture<Void>> futures = new ArrayList<>(algoIds.size());
    for (String id : algoIds) {
        futures.add(CompletableFuture.runAsync(() -> {
            try {
                AlgoDetailResponse r = queryOne(id);
                if (r != null) {
                    result.put(id, r);
                }
            } catch (Exception e) {
                // 单条失败只记日志，不中断整批
                log.warn("query algo detail failed, id: {}", id, e);
            }
        }, POOL));
    }
    CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
    return result;
}
